import{_ as t,l as s,o as a,c as l,v as o,p as d,x as r,d as i,i as n,S as A}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"原子指令：LR/SC 与 CAS","description":"","frontmatter":{"title":"原子指令：LR/SC 与 CAS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lr-sc-cas.md","filePath":"cs/lr-sc-cas.md","lastUpdated":1789023840000}'),S={name:"cs/lr-sc-cas.md"};function h(p,e,C,E,R,m){const c=s("Mermaid");return a(),l("div",null,[e[1]||(e[1]=o('<h1 id="原子指令-lr-sc-与-cas" tabindex="-1">原子指令：LR/SC 与 CAS <a class="header-anchor" href="#原子指令-lr-sc-与-cas" aria-label="Permalink to &quot;原子指令：LR/SC 与 CAS&quot;">​</a></h1><div class="epigraph"><p>多核要在内存上读改写而不夹缝：比较并交换一次给新值，或先保留加载再条件存储，失败则软件重试。</p><footer>—— 据 The RISC-V Instruction Set Manual；ARM ARM；Intel SDM；Herlihy and Shavit, The Art of Multiprocessor Programming 整理</footer></div><p><a href="/cs/arm-vs-riscv">上一课</a>把两家 RISC 放到同一家族。组成/体系结构的缓存一致性假定有原子原语。缺口是 ISA 如何暴露：<strong>CAS</strong>（x86 <code>lock cmpxchg</code>，ARM LSE）与 <strong>LR/SC</strong>（RISC-V <code>lr</code>/<code>sc</code>，ARM <code>ldxr</code>/<code>stxr</code>）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>lock; add</code> 一类 RMW 在缓存行上获取排他。CAS：读、比较、相等才写，返回旧值。LR/SC：<code>lr</code> 登记保留集，若中间无干扰 <code>sc</code> 成功。缺口不是 MESI 状态名，而是<strong>软件循环</strong>：CAS 失败重试；SC 失败重试；ABA 要用标签或 LL/SC 的保留语义缓解。</p><p>AMO（RISC-V <code>amoadd</code>）把常见 RMW 做成单指令，减少循环。x86 的 <code>lock</code> 前缀给读改写指令。</p><h3 id="lr-sc-不是「总线锁住到-sc」" tabindex="-1">LR/SC 不是「总线锁住到 sc」 <a class="header-anchor" href="#lr-sc-不是「总线锁住到-sc」" aria-label="Permalink to &quot;LR/SC 不是「总线锁住到 sc」&quot;">​</a></h3><p>现代实现用缓存保留，干涉可能来自一致性失效或异常。过于复杂的保留窗口里插太多指令，实现允许 <code>sc</code> 一直失败（前进保证是架构约束）。把 LR/SC 当关中断的临界区，多核仍会打架。</p><p><span class="marginnote">RISC-V <code>A</code> 扩展；ARM 独占监视器；Intel <code>cmpxchg</code>。Herlihy/Shavit 给无锁算法背景。本课不写完整 C++ memory_order 表——下一课 fence。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>自旋锁：CAS 把 0 改 1。无锁栈：CAS 改头指针。RISC-V：<code>lr.w; 改寄存器; sc.w</code> 循环。ARM：<code>ldaxr/stlxr</code> 带获取/释放变体。失败开销：缓存行来回，与 <a href="/cs/row-buffer-bank-conflict">DRAM</a> 无关但与一致性流量有关。</p>',11)),(a(),d(A,null,{default:r(()=>[n(c,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAS%5B%22CAS%20%E6%AF%94%E8%BE%83%E5%86%99%22%5D%20--%3E%20RETRY%5B%22%E5%A4%B1%E8%B4%A5%E9%87%8D%E8%AF%95%22%5D%0A%20%20LRSC%5B%22LR%20%E4%BF%9D%E7%95%99%20%2F%20SC%20%E6%9D%A1%E4%BB%B6%E5%86%99%22%5D%20--%3E%20RETRY%0A%20%20AMO%5B%22AMO%20%E5%8D%95%E6%8C%87%E4%BB%A4%20RMW%22%5D%20--%3E%20LOCK%5B%22%E9%94%81%E4%B8%8E%E6%97%A0%E9%94%81%E5%8E%9F%E8%AF%AD%22%5D%0A%20%20RETRY%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%BA%8F%E8%BF%98%E8%A6%81%20fence%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>I/O 设备寄存器通常不可用 CAS 当锁，除非规范说可以；MMIO 副作用不同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下一课内存序：原子指令往往自带 acquire/release 变体，普通 store 仍可重排。本课只钉「不可分割的读改写」。微码 x86 <code>lock</code> 前缀让那条指令的 μop 带锁前缀语义。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证明线性一致性全部定理，不把 STM 写进来。不讨论 GPU atomics 的作用域。不进入交易所撮合——禁止限价簿。</p><p>后课默认：多核同步用 CAS 或 LR/SC（及 AMO）；失败重试；ABA 要额外设计。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CAS 一次比较并写；LR/SC 两拍保留。</li><li>实现靠缓存排他，不是关中断。</li><li>成功仍可能需要 fence 才能看见数据。</li><li>出处：RISC-V ISA；ARM ARM；Intel SDM；Herlihy and Shavit。</li></ul>',8))])}const u=t(S,[["render",h]]);export{f as __pageData,u as default};
